set -eu; n=deploy-gaybbs-1; files=$(docker inspect -f '{{index .Config.Labels "com.docker.compose.project.config_files"}}' "$n"); wd=$(docker inspect -f '{{index .Config.Labels "com.docker.compose.project.working_dir"}}' "$n"); old=$(docker inspect -f '{{.Config.Image}}' "$n"); docker compose -f "$files" --project-directory "$wd" config --format json > /tmp/gace-roompos-compose.json; python3 - "$old" <<'PY'
import json,sys
x=json.load(open("/tmp/gace-roompos-compose.json"))
s=x.get("services",{}).get("gaybbs",{})
if not s: sys.exit(71)
if s.get("image")!=sys.argv[1]: sys.exit(72)
if s.get("pull_policy")=="always": sys.exit(73)
if not s.get("image"): sys.exit(74)
print("COMPOSE_SERVICE_IMAGE_MATCH=PASS")
PY
